<script setup lang="ts">
import {computed,ref,watch,onBeforeUnmount} from 'vue';
import {usePlatform} from '../stores/platform';
import {request,isRequestCanceled} from '../api/client';
import type {Response} from '../api/client';
import {profileLinkFilter} from '../api/resources';
import {localTime} from '../domain';
import RemoteAssetImage from './RemoteAssetImage.vue';
import QueryForm from './QueryForm.vue';
import DataTable from './DataTable.vue';
const labels:Record<string,string>={nameMasked:'姓名',gender:'性别',ethnicity:'民族',phoneMasked:'手机号码',identityNumberMasked:'身份证号码',residenceRegionCode:'常驻地区',suspectedSiteId:'疑似落脚场所',portraitAssetId:'画像编号',appearanceDescription:'外貌特征',suspectedLandingText:'疑似落脚点',plateNumberMasked:'车牌号码',brand:'品牌',model:'型号',color:'颜色'};
const p=usePlatform(),error=ref(''),loading=ref(false),tab=ref('FENCE'),modelId=ref(''),tag=ref('');
const targets=ref<Response<'listProfileTargets'>['data']['items']>([]),evidence=ref<Response<'listProfileEvidence'>['data']['items']>([]),modelResults=ref<Response<'listTrendModelResults'>['data']['items']>([]);
const targetCursor=ref<string|null>(null),evidenceCursor=ref<string|null>(null),modelCursor=ref<string|null>(null);let controller=new AbortController();
const profile=computed(()=>p.detail?.kind==='profile'&&p.detail.id===p.remote.profile?.profileId?p.remote.profile:null),trend=computed(()=>p.active==='数据态势');
async function load(next=false){controller.abort();controller=new AbortController();loading.value=true;error.value='';try{if(trend.value){if(!modelId.value){modelResults.value=[];return;}const r=(await request('listTrendModelResults',{path:{modelId:modelId.value},query:{pageSize:20,cursor:next?modelCursor.value||undefined:undefined,tagCode:tag.value||undefined},signal:controller.signal})).data;modelResults.value=next?[...modelResults.value,...r.items]:r.items;modelCursor.value=r.nextCursor;}else if(p.detail?.kind==='profile'){const id=p.detail.id;const [a,b]=await Promise.all([request('listProfileTargets',{path:{profileId:id},query:{dataType:tab.value as 'FENCE'|'PLATE'|'MAC'|'FACE',pageSize:20,cursor:next?targetCursor.value||undefined:undefined},signal:controller.signal}),request('listProfileEvidence',{path:{profileId:id},query:{pageSize:20,cursor:next?evidenceCursor.value||undefined:undefined},signal:controller.signal})]);targets.value=next?[...targets.value,...(targetCursor.value?a.data.items:[])]:a.data.items;evidence.value=next?[...evidence.value,...(evidenceCursor.value?b.data.items:[])]:b.data.items;targetCursor.value=a.data.nextCursor;evidenceCursor.value=b.data.nextCursor;}}catch(e){if(!isRequestCanceled(e))error.value=e instanceof Error?e.message:String(e);}finally{loading.value=false;}}
watch([()=>p.detail?.id,()=>p.remote.profile?.profileId,tab,modelId,tag],()=>void load());watch(()=>p.remote.models,models=>{if(!models.some(m=>m.modelId===modelId.value))modelId.value=models[0]?.modelId||'';},{immediate:true,deep:true});onBeforeUnmount(()=>controller.abort());
function trajectory(id:string){const end=new Date(),start=new Date(end.getTime()-86400000);const input=(date:Date)=>date.toLocaleString('sv-SE',{timeZone:'Asia/Shanghai'}).replace(' ','T').slice(0,16);p.navigate('地图研判',{profileId:id,type:'综合',start:input(start),end:input(end)});p.mapTrajectory=true;}
function search(row:Record<string,unknown>){const link=targets.value.find(t=>t.linkId===row.id);if(!link)return;const type=link.target.targetType==='PLATE'?'车牌':link.target.targetType==='MAC'?'MAC':link.target.targetType==='FACE'?'人像':'电围';p.navigate(type==='车牌'?'车牌检索':type==='MAC'?'MAC检索':type==='人像'?'人像检索':'围栏检索',profileLinkFilter(link));}
</script>
<template><el-alert v-if="error" type="error" :title="error" :closable="false"/><template v-if="trend"><section class="card section-head"><h3>常驻数据模型库</h3><el-button type="primary" @click="p.formModel()">创建模型</el-button></section><DataTable :rows="p.remote.models.map(m=>({id:m.modelId,name:m.name,tags:m.tagCodes.join('、'),enabled:m.enabled,parameterVersion:m.currentParameterVersionId||'未设置'}))" :columns="[{key:'name',label:'模型名称',link:true},{key:'tags',label:'数据标签'},{key:'enabled',label:'启用状态'},{key:'parameterVersion',label:'参数版本'}]" @open="row=>p.formModel(String(row.id))"/><section class="card"><el-form inline><el-form-item label="结果模型"><el-select v-model="modelId" aria-label="结果模型"><el-option v-for="model in p.remote.models" :key="model.modelId" :label="model.name" :value="model.modelId"/></el-select></el-form-item><el-form-item label="数据标签"><el-select v-model="tag" aria-label="数据标签" clearable><el-option v-for="code in p.remote.models.find(m=>m.modelId===modelId)?.tagCodes||[]" :key="code" :label="code" :value="code"/></el-select></el-form-item><el-button :loading="loading" @click="load()">刷新结果</el-button></el-form></section><DataTable :rows="modelResults.map(r=>({id:r.resultId,target:r.displayTarget,tags:r.tagCodes.join('、'),confidence:r.confidence==null?'未评估':(r.confidence*100).toFixed(1)+'%',review:r.reviewStatus,version:r.algorithmVersion,time:localTime(r.generatedAt)}))" :columns="[{key:'target',label:'目标标识'},{key:'tags',label:'符合模型标签'},{key:'confidence',label:'置信度'},{key:'review',label:'复核状态'},{key:'version',label:'模型版本'},{key:'time',label:'生成时间'}]" :selectable="false" title="标签结果"/><el-button v-if="modelCursor" @click="load(true)">加载更多模型结果</el-button></template><template v-else-if="profile"><section class="card"><div class="section-head"><h3>{{profile.profileType==='PERSON'?'一人一档':'一车一档'}} · {{profile.displayLabel}}</h3><el-button @click="trajectory(profile.profileId)">综合轨迹查看</el-button></div><RemoteAssetImage v-if="profile.profileType==='PERSON'" :asset-id="profile.person.portraitAssetId" :alt="profile.displayLabel"/><el-descriptions :column="2" border><el-descriptions-item v-for="(value,key) in profile.profileType==='PERSON'?profile.person:profile.vehicle" :key="key" :label="labels[String(key)]||String(key)">{{value??'暂无资料'}}</el-descriptions-item><el-descriptions-item label="采集总次数">{{profile.captureCount}}</el-descriptions-item><el-descriptions-item label="经过站点">{{profile.siteCount}}</el-descriptions-item><el-descriptions-item label="经过区域">{{profile.visitedRegionCodes?.join('、')||'暂无资料'}}</el-descriptions-item><el-descriptions-item label="档案置信度">{{profile.confidence==null?'未评估':(profile.confidence*100).toFixed(1)+'%'}}</el-descriptions-item></el-descriptions><el-tabs v-model="tab"><el-tab-pane v-for="item in [{value:'FENCE',label:'电围'},{value:'MAC',label:'MAC'},{value:'PLATE',label:'车牌'},{value:'FACE',label:'人像'}]" :key="item.value" :name="item.value" :label="item.label"/></el-tabs></section><DataTable :rows="targets.map(t=>({id:t.linkId,target:t.displayTarget,source:t.source,review:t.reviewStatus,confidence:t.confidence==null?'未评估':(t.confidence*100).toFixed(1)+'%'}))" :columns="[{key:'target',label:'关联目标'},{key:'source',label:'证据来源'},{key:'review',label:'复核状态'},{key:'confidence',label:'关联置信度'}]" :selectable="false" title="关联数据"><template #rowActions="{row}"><el-button link type="primary" @click="search(row)">检索</el-button></template></DataTable><DataTable :rows="evidence.map(e=>({id:e.evidenceId,capture:e.captureId,source:e.source,version:e.sourceVersion,relation:e.relation,review:e.reviewStatus,time:localTime(e.collectedAt)}))" :columns="[{key:'capture',label:'采集证据 ID'},{key:'source',label:'来源'},{key:'version',label:'来源版本'},{key:'relation',label:'关联关系'},{key:'review',label:'复核状态'},{key:'time',label:'证据时间'}]" :selectable="false" title="关联证据"/><el-button v-if="targetCursor||evidenceCursor" :loading="loading" @click="load(true)">加载更多关联资料</el-button></template><template v-else><QueryForm :model="p.f" :fields="[...(p.active==='图码档案'?[{key:'searchBy',label:'查询类型',options:['外貌','特征码','姓名']}]:[]),{key:'keyword',label:p.active==='车码档案'?'车牌 / 特征码':'外貌 / 特征码 / 姓名'}]" @search="p.query" @reset="p.reset"/><section class="card"><div class="profile-gallery"><article v-for="r in p.remote.profiles" :key="r.profileId" class="profile-card"><div class="portrait-placeholder">档案画像</div><div><h3>{{r.displayLabel}}</h3><el-button @click="p.openDetail('profile',r.profileId)">基本资料 / 关联数据</el-button><el-button type="primary" @click="trajectory(r.profileId)">综合轨迹</el-button></div></article></div><el-empty v-if="!p.remote.profiles.length" description="无匹配档案"/></section></template></template>
